        const afterRes = await tx.query('SELECT position FROM cards WHERE id = $1', [afterId]);

        if (beforeRes.rows.length > 0 && afterRes.rows.length > 0) {
          newPosition = (beforeRes.rows[0].position + afterRes.rows[0].position) / 2;
