      // Get the final state of the card to return to client
      const finalCardRes = await tx.query('SELECT * FROM cards WHERE id = $1', [id]);
      const finalCard = finalCardRes.rows[0];

      // Broadcast the move
      broadcast('card_moved', { columnId, card: finalCard });

