  color: #ffffff;
}

body {
  margin: 0;
  display: flex;
  place-items: center;
  min-width: 320px;
  min-height: 100vh;
}

#app {
  width: 100%;
  margin: 0 auto;
  padding: 2rem;
  text-align: center;
}

.board {
  display: flex;
  gap: 20px;
  align-items: flex-start;
  justify-content: center;
  padding: 20px;
}

.column {
  background-color: #333;
  border-radius: 8px;
  width: 300px;
  min-height: 400px;
  display: flex;
  flex-direction: column;
  padding: 10px;
}

.column h2 {
  margin-top: 0;
  font-size: 1.2rem;
  padding: 0 10px;
  text-align: left;
}

.cards-container {
  flex-grow: 1;
  min-height: 100px;
}

.card {
  background-color: #444;
  border-radius: 4px;
  padding: 10px;
  margin: 8px 0;
  cursor: grab;
  text-align: left;
