  flex-grow: 1;
  padding: 5px;
  border-radius: 4px;
  border: 1px solid #555;
  background: #222;
  color: white;
}

.add-card-form button {
  padding: 5px 10px;
  border-radius: 4px;
  border: none;
  background-color: #646cff;
  color: white;
  cursor: pointer;
}

.add-card-form button:hover {
  background-color: #535bf2;
}
