    const offset = y - box.top - box.height / 2;
    const isAfter = offset < 0;

    if (isAfter && (!afterElement || offset < afterElement.offset)) {
       return { element: currentElement, offset: offset };
    } else {
       return { element: afterElement, offset: afterElement.offset };
    }
  }, { element: null, offset: Number.POSITIVE_INFINITY }).element;
