      let afterId = null;

      if (cardIdx > 0) {
        beforeId = cardsInCol[cardIdx - 1].dataset.id;
      }
      if (cardIdx < cardsInCol.length - 1) {
        afterId = cardsInCol[cardIdx + 1].dataset.id;
      }

